// Server-only brand helpers shared by every PDF renderer: the embedded Branta
// Tech logos (colour + white) and the "generated by / device" footer line.
import type { PDFDocument, PDFImage } from "pdf-lib";
import { BRAND_LOGO_COLOR_B64 } from "./logo-color.server";
import { BRAND_LOGO_WHITE_B64 } from "./logo-white.server";

export type GeneratedBy = { name?: string | null; device?: string | null };

function b64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Embeds the built-in brand logo (PNG) into a pdf-lib document. */
export async function embedBrandLogo(
  pdf: PDFDocument,
  variant: "color" | "white",
): Promise<PDFImage | null> {
  try {
    return await pdf.embedPng(
      b64ToBytes(variant === "white" ? BRAND_LOGO_WHITE_B64 : BRAND_LOGO_COLOR_B64),
    );
  } catch {
    return null;
  }
}

/** "Chrome on macOS" style label parsed from a request user-agent. */
export function deviceFromUserAgent(ua?: string | null): string {
  const s = ua ?? "";
  if (!s) return "Unknown device";
  const browser =
    /Edg\//.test(s) ? "Edge"
      : /OPR\//.test(s) ? "Opera"
        : /Firefox\//.test(s) ? "Firefox"
          : /Chrome\//.test(s) ? "Chrome"
            : /Safari\//.test(s) ? "Safari"
              : "Browser";
  const os =
    /iPhone|iPad|iPod/.test(s) ? "iOS"
      : /Android/.test(s) ? "Android"
        : /Mac OS X|Macintosh/.test(s) ? "macOS"
          : /Windows/.test(s) ? "Windows"
            : /Linux/.test(s) ? "Linux"
              : "Unknown OS";
  return `${browser} on ${os}`;
}

export function dhakaTimestamp(d: Date = new Date()): string {
  return `${d.toLocaleString("en-GB", {
    timeZone: "Asia/Dhaka",
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  })} (GMT+6)`;
}

/** One compact provenance line printed at the bottom of every PDF. */
export function generatedByLine(g?: GeneratedBy | null, when: Date = new Date()): string {
  const who = g?.name?.trim() ? `Generated by ${g.name.trim()}` : "Generated via shared link";
  const dev = g?.device?.trim();
  return [who, dev, dhakaTimestamp(when)].filter(Boolean).join("  ·  ");
}

/** Company helpline printed on every branded PDF. */
export const BRAND_HOTLINE = "09644228678";

/** Official Branta Tech mailboxes, always listed on PDF footers. */
export const BRAND_EMAILS = [
  "hr@brantatech.org",
  "accounts@brantatech.org",
  "sales@brantatech.org",
  "support@brantatech.org",
] as const;

/** Email list for footers: the four official mailboxes plus any custom one. */
export function brandEmailList(extra?: string | null): string {
  const all: string[] = [...BRAND_EMAILS];
  const e = extra?.trim();
  if (e && !all.includes(e)) all.push(e);
  return all.join(" · ");
}
